namespace{bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
using namespace ks;
struct Resolver{StateFieldCoordinator::Handler field(uint8_t c,uint32_t p){constexpr unsigned a[]{0x4f4a,0x4f06,0x51d8,0x51f4,0x5252,0x4f22,0x51fe,0x4f0c,0xb554};if(c>=9||p!=a[c])throw std::logic_error("Unsupported encoder field binding");return StateFieldCoordinator::Handler(c);}bool schema(uint8_t c,uint32_t p){switch(c){case 0:return p==0x4f4a;case 2:return p==0x51d8;case 3:return p==0x51f4;case 4:return p==0x5252;case 6:return p==0x51fe;default:return false;}}StatePackFieldsTask::Kind operator()(uint32_t p){constexpr unsigned a[]{0x68b0,0x68de,0x6922,0x6944,0x6970,0x69a6};for(unsigned n=0;n<6;++n)if((p&0xffffff)==a[n])return StatePackFieldsTask::Kind(n);throw std::logic_error("Unsupported encoder packing binding");}};
int main(){try{using T=ks::NativeMidiControlService;using K=T::Kind;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;Resolver resolver;
for(unsigned kind=0;kind<3;++kind)for(unsigned key:{0u,1u,2u,3u,6u,11u,32u,64u,98u,104u,120u,121u,122u,123u,124u,125u,126u,127u,255u})for(unsigned value:{0u,63u,64u,127u,255u}){std::fill(m.begin()+0xb8e8,m.begin()+0x30000,uint8_t(0));const auto wide=[&](unsigned a,uint32_t v){for(unsigned n=0;n<4;++n)m[a+n]=uint8_t(v>>(24-8*n));};const auto word=[&](unsigned a,uint16_t v){m[a]=uint8_t(v>>8);m[a+1]=uint8_t(v);};wide(0x167bc,0x18000);wide(0x167c0,0x19000);m[0x17526]=2;wide(0x174ae + 40,0x18000);m[0x174ae + 40+17]=1;m[0x174a6]=4;for(unsigned i=0;i<14;++i){wide(0x17560+20*i,0x18000);m[0x17560+20*i+4]=2;m[0x17560+20*i+5]=60;wide(0x17560+20*i+8,0x10000);}m[0x160d2+668+309]=16;m[0x160d2+668+332]=uint8_t(value);m[0x167ba]=m[0x167bb]=0;m[0x16798]=m[0x167d4]=2;m[0x1679a]=0;m[0x158f2]=4;m[0x1678d]=99;for(unsigned i=0;i<256;++i){m[71842+i]=uint8_t(i%128);m[71586+i]=uint8_t(i%4==0?126:0);m[0x18000+i]=uint8_t(i+1);}m[0x18000]=16;m[0x18001]=17;m[0x180b1]=1;m[0x18058]=0;for(unsigned j=0;j<66;++j)word(0x15200+2*j,uint16_t(j*511));word(0x15130,0x3c00);word(0x17516,256);m[0x17518]=10;m[0x17519]=20;m[0x1751a]=30;m[0x169f0]=m[0x17521]=64;m[0x15c1f]=uint8_t(key);m[0x15c20]=uint8_t(value);for(unsigned d=0;d<4;++d){wide(72134+4*d,0x12000+256*d);const unsigned desc=0x12000+256*d;m[desc]=d;m[desc+1]=64;m[desc+2]=3;for(unsigned i=4;i<256;i+=2){m[desc+i]=uint8_t(i%8);m[desc+i+1]=uint8_t(i/2);}}
unsigned count=0;int previous=-1;tracking=true;{T t(K(kind),{0x15c1f,0x18000,0,2});while(!t.complete()){struct Unowned{};check(!t.task<Unowned>(),"Unknown MIDI control query");const auto cost=t.nextClocks(previous);check(cost>0,"Control pure stalled");std::array<unsigned char,sizeof(T)>saved{};std::memcpy(saved.data(),&t,sizeof(T));unsigned callbacks=0;check(t.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},resolver,previous)==0&&!callbacks&&!std::memcmp(saved.data(),&t,sizeof(T)),"Control budget changed object");++rejects;const auto read=[&](uint32_t a,unsigned dt){check(a<(1u<<24)&&dt<=cost,"Control pure read bound");++reads;return a==0x400004||a==0x600004?uint8_t(255):m[a];};const auto write=[&](uint32_t a,uint8_t v,unsigned dt){check(a<(1u<<24)&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Control pure write bound");++writes;m[a]=v;previous=a<0x400000?int(a):-1;};check(t.advanceBefore(cost,read,write,resolver,previous)==cost,"Control pure admission");if(t.effect().write)previous=-1;check(++count<1000000,"Control pure did not complete");++phases;}
if(kind==2&&key==32)check(m[0x160d2+668+331]==value,"CC bank oracle");if(kind==2&&key==64)check(m[0x160d2+668+309]==(value<64?0:16),"CC sustain oracle");components|=t.components();}tracking=false;++graphs;}
check(components==127&&!allocations,"Control pure coverage/heap");std::cout<<"PASS Pure NativeMidiControl graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;
}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
